(()=>{const bind=()=>{const items=[...document.querySelectorAll('.nav span')];items.forEach((item,index)=>item.addEventListener('click',()=>{items.forEach(x=>x.classList.remove('on'));item.classList.add('on');document.querySelector('.side')?.setAttribute('data-section',String(index))}))};if(window.BX24)BX24.init(bind);else addEventListener('load',bind)})();
