/* Личный кабинет обменов: отдельный слой, не вмешивается в загрузку календаря. */
(()=>{
  let headers={};
  const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  async function api(path,method='GET',body){const response=await fetch(path,{method,headers:{...headers,...(body?{'content-type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.error||'Не удалось выполнить действие');return data}
  function show(data){
    const me=data.employees.find(item=>item.id===data.currentEmployeeId);if(!me)return;
    const balance=data.balances.find(item=>item.id===me.id)?.hours||0;
    const today=new Date(),todayKey=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;
    const mine=data.duties.filter(item=>Number(item.employee_id)===Number(me.id)&&item.ends_on>=todayKey);
    const incoming=data.swapRequests.filter(item=>item.to_employee_id===me.id&&item.status==='pending_target');
    const admin=data.permissions.canEdit?data.swapRequests.filter(item=>item.status==='pending_admin'):[];
    const people=data.employees.filter(item=>item.id!==me.id).map(item=>`<option value="${item.id}">${esc(item.name)}</option>`).join('');
    document.querySelector('.main').innerHTML=`<div class="report-page"><header class="top"><div><div class="eyebrow">novoi.bitrix24.kz</div><h1>Мой баланс и обмены</h1><div class="sub">Баланс: <b>${balance} ч</b> к компенсации</div></div></header><section class="report-card"><h2>Предложить замену</h2><p class="muted">Выберите своё назначенное дежурство и сотрудника. Он должен согласиться, после чего администратор подтверждает обмен.</p>${mine.length?mine.map(duty=>`<form class="swap-form" data-duty="${duty.id}" style="display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:10px;align-items:end;margin-top:12px"><div><b>${duty.kind==='office'?'Офис':'Поддержка'} · ${friendlyPeriod(duty.starts_on,duty.ends_on)}</b><div class="muted">${duty.hours} ч</div></div><select name="to_employee_id">${people}</select><button>Предложить обмен</button><input style="grid-column:1/-1" name="note" placeholder="Комментарий для сотрудника (необязательно)">${data.permissions.canEdit?`<button type="button" data-remind="${duty.id}" style="grid-column:1/-1">Отправить напоминание сейчас</button>`:''}</form>`).join(''):'<div class="empty-note">У вас нет назначенных дежурств, которые можно обменять.</div>'}</section><section class="report-card"><h2>Мне предложили обмен</h2>${incoming.length?`<table class="report-table"><tr><th>От кого</th><th>Период</th><th>Часы</th><th></th></tr>${incoming.map(item=>`<tr><td>${esc(item.from_name)}</td><td>${friendlyPeriod(item.starts_on,item.ends_on)}</td><td>${item.hours} ч</td><td><button data-accept="${item.id}">Согласиться</button> <button class="danger" data-reject-swap="${item.id}">Отклонить</button></td></tr>`).join('')}</table>`:'<div class="empty-note">Новых предложений нет.</div>'}</section>${data.permissions.canEdit?`<section class="report-card"><h2>Обмены на подтверждении</h2>${admin.length?`<table class="report-table"><tr><th>Кто меняется</th><th>Период</th><th></th></tr>${admin.map(item=>`<tr><td>${esc(item.from_name)} → ${esc(item.to_name)}</td><td>${friendlyPeriod(item.starts_on,item.ends_on)} · ${item.hours} ч</td><td><button class="primary" data-approve="${item.id}">Подтвердить обмен</button> <button class="danger" data-reject-swap="${item.id}">Отклонить</button></td></tr>`).join('')}</table>`:'<div class="empty-note">Нет обменов, ожидающих решения администратора.</div>'}</section>`:''}<p><button onclick="location.reload()">← К календарю</button></p></div>`;
    const reportYear=String(new Date().getFullYear()),myAbsences=data.absences.filter(item=>item.employee_id===me.id&&item.occurred_on.startsWith(reportYear)),myDuties=data.duties.filter(item=>item.employee_id===me.id),confirmed=myDuties.filter(item=>item.status==='confirmed'),months=['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'];
    const monthly=months.map((label,index)=>{const prefix=`${reportYear}-${String(index+1).padStart(2,'0')}`;return {label,absence:myAbsences.filter(item=>item.occurred_on.startsWith(prefix)).reduce((sum,item)=>sum+Number(item.hours),0),duty:confirmed.filter(item=>item.ends_on.startsWith(prefix)).reduce((sum,item)=>sum+Number(item.hours),0)}}),maxMonth=Math.max(1,...monthly.flatMap(item=>[item.absence,item.duty]));
    const events=[...myAbsences.map(item=>({date:item.occurred_on,type:({vacation:'Отпуск',sick_leave:'Больничный',time_off:'Отгул',business_trip:'Командировка',personal:'Личное отсутствие',other:'Другое'}[item.absence_type]||'Отсутствие'),detail:`${item.hours} ч${item.compensable?' · в отработке':''}`})),...myDuties.map(item=>({date:item.ends_on,type:item.kind==='office'?'Офисное дежурство':'Поддержка',detail:`${item.hours} ч · ${item.status==='confirmed'?'подтверждено':'назначено'}`}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);
    const team=data.permissions.canEdit?data.employees.map(employee=>{const absence=data.absences.filter(item=>item.employee_id===employee.id&&item.occurred_on.startsWith(reportYear)).reduce((sum,item)=>sum+Number(item.hours),0),debt=Math.abs(Math.min(0,Number(data.balances.find(item=>item.id===employee.id)?.hours||0)));return {name:employee.name,absence,debt}}).sort((a,b)=>b.absence-a.absence):[];const teamMax=Math.max(1,...team.map(item=>item.absence));
    const dashboard=`<section class="cabinet-grid"><div class="cabinet-stat"><b>${balance} ч</b><span>текущий баланс</span></div><div class="cabinet-stat"><b>${myAbsences.reduce((sum,item)=>sum+Number(item.hours),0)} ч</b><span>отсутствий за ${reportYear} год</span></div><div class="cabinet-stat"><b>${confirmed.length}</b><span>подтверждённых дежурств</span></div></section><section class="cabinet-section"><h2>Моя активность за ${reportYear} год</h2><div class="sub">Отсутствия и подтверждённые дежурства по месяцам</div><div class="month-chart">${monthly.map(item=>`<div class="month-col"><div class="month-bars"><i class="absence" title="Отсутствия: ${item.absence} ч" style="height:${Math.max(item.absence?8:0,item.absence/maxMonth*118)}px"></i><i class="duty" title="Дежурства: ${item.duty} ч" style="height:${Math.max(item.duty?8:0,item.duty/maxMonth*118)}px"></i></div><small>${item.label}</small></div>`).join('')}</div><div class="chart-legend"><span><i style="background:#f09976"></i>Отсутствия</span><span><i style="background:#3975ec"></i>Дежурства</span></div></section><section class="cabinet-section"><h2>Последние события</h2>${events.length?events.map(item=>`<div class="timeline-item"><span class="sub">${friendlyPeriod(item.date,item.date)}</span><span class="timeline-type">${esc(item.type)}</span><span>${esc(item.detail)}</span></div>`).join(''):'<div class="empty-note">Записей за этот год пока нет.</div>'}</section>${data.permissions.canEdit?`<section class="cabinet-section"><h2>Команда: отсутствия за ${reportYear} год</h2><div class="sub">Сортировка по общему времени отсутствий; долг по дежурствам показан отдельно.</div><div class="team-compact">${team.map(item=>`<div class="team-row"><b>${esc(item.name)}</b><span>${item.absence} ч</span><div class="team-track"><i style="width:${item.absence/teamMax*100}%"></i></div><span class="sub">долг ${item.debt} ч</span></div>`).join('')||'<div class="empty-note">Нет данных.</div>'}</div></section>`:''}`;
    document.querySelector('.report-page header').insertAdjacentHTML('afterend',dashboard);
    document.querySelectorAll('.swap-form select').forEach(select=>{const label=document.createElement('label');label.className='swap-select';label.innerHTML='<span>Кому передать дежурство</span>';select.before(label);label.append(select)});
    document.querySelectorAll('.swap-form').forEach(form=>{const duty=data.duties.find(item=>String(item.id)===String(form.dataset.duty));if(duty?.status==='confirmed')form.insertAdjacentHTML('beforeend','<div class="sub" style="grid-column:1/-1">Дежурство подтверждено, но обмен возможен: после одобрения администратора учёт будет перенесён на нового сотрудника.</div>')});
    document.querySelectorAll('.swap-form').forEach(form=>form.onsubmit=async event=>{event.preventDefault();try{await api('/api/swaps','POST',{duty_id:form.dataset.duty,...Object.fromEntries(new FormData(form))});alert('Предложение отправлено сотруднику.');open()}catch(error){alert(error.message)}});
    document.querySelectorAll('[data-accept]').forEach(button=>button.onclick=()=>action(button.dataset.accept,'accept'));
    document.querySelectorAll('[data-approve]').forEach(button=>button.onclick=()=>action(button.dataset.approve,'approve'));
    document.querySelectorAll('[data-reject-swap]').forEach(button=>button.onclick=()=>action(button.dataset.rejectSwap,'reject'));
    document.querySelectorAll('[data-remind]').forEach(button=>button.onclick=async()=>{try{await api(`/api/duties/${button.dataset.remind}/remind`,'POST');alert('Напоминание отправлено в чат сотрудника.')}catch(error){alert(error.message)}});
  }
  async function action(id,verb){if(verb==='reject'&&!confirm('Отклонить обмен?'))return;try{await api(`/api/swaps/${id}/${verb}`,'POST');alert(verb==='approve'?'Обмен подтверждён.':'Решение сохранено.');open()}catch(error){alert(error.message)}}
  async function open(){try{show(await api('/api/bootstrap'))}catch(error){alert(error.message)}}
  function bind(){if(window.BX24){const auth=BX24.getAuth?.();if(auth)headers={'x-b24-token':auth.access_token,'x-b24-domain':auth.domain}}const nav=[...document.querySelectorAll('.nav span')];if(nav[1])nav[1].onclick=open}
  if(window.BX24)BX24.init(bind);else window.addEventListener('load',bind);
})();

/* Переход в календарь через пункт левого меню из любого раздела. */
(()=>{const bind=()=>{document.querySelectorAll('.nav span')[0]?.addEventListener('click',()=>location.reload())};if(window.BX24)BX24.init(bind);else addEventListener('load',bind)})();
/* Явные действия для получателя заявки на обмен. */
