(()=>{const style=document.createElement('style');style.textContent='.settings-audit{max-height:370px;overflow:auto;padding-right:6px}.settings-audit::-webkit-scrollbar{width:6px}.settings-audit::-webkit-scrollbar-thumb{background:#d5ddeb;border-radius:10px}.settings-audit-row{display:grid;grid-template-columns:34px minmax(0,1fr);gap:10px;padding:11px 0;border-top:1px solid #edf1f6}.settings-audit-row:first-child{border-top:0}.settings-audit-row .ava{width:32px;height:32px;object-fit:cover;font-size:10px}.settings-audit-row b,.settings-audit-row span,.settings-audit-row small{display:block}.settings-audit-row b{font-size:13px;color:#243551}.settings-audit-row span{margin-top:2px;color:#4f668d;font-size:12px;font-weight:700}.settings-audit-row small{margin-top:3px;color:#8190a8;font-size:12px;line-height:1.35}';document.head.append(style)})();

/* Фильтры и таблица аналитики сотрудников. */
(()=>{const style=document.createElement('style');style.textContent='.employee-analytics{overflow:hidden}.employee-report-head{display:flex;justify-content:space-between;gap:16px}.employee-report-head h2{margin-bottom:4px}.stats-filters{display:flex;align-items:end;gap:10px;flex-wrap:wrap;margin:18px 0;padding:13px;background:#f6f8fd;border:1px solid #e5ebf5;border-radius:12px}.stats-filters label{display:grid;gap:5px;color:#65748e;font-size:11px;font-weight:700}.stats-filters select,.stats-filters input{min-height:38px;border:1px solid #d9e2ef;border-radius:8px;background:#fff;color:#23314b;padding:7px 9px;font:13px Inter,system-ui,sans-serif}.stats-filters button{min-height:38px;font-size:12px}.filter-divider{color:#98a5ba;font-size:12px;padding:0 2px 10px}.stat-kpis{margin:0 0 13px}.period-caption{font-size:12px;color:#72819a;margin-bottom:5px}.reasons{max-width:300px;white-space:normal}.report-table-wrap{overflow:auto}.roster-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.roster-head h2{margin-bottom:4px}.roster-scroll{max-height:330px;overflow:auto;margin-top:12px;padding-right:5px}.roster-scroll::-webkit-scrollbar{width:6px}.roster-scroll::-webkit-scrollbar-thumb{background:#d4ddea;border-radius:8px}.roster-scroll .report-table{margin-top:0}.roster-scroll th{position:sticky;top:0;background:#fff;z-index:1}@media(max-width:760px){.stats-filters{display:grid;grid-template-columns:1fr 1fr}.filter-divider{display:none}.stats-filters button{grid-column:1/-1}.stat-kpis{grid-template-columns:1fr 1fr}.reasons{max-width:180px}}';document.head.append(style)})();
